package com.rulecraft.decisionops.versions;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.DecisionServiceStatus;import com.rulecraft.decisionops.catalog.persistence.DecisionServiceRepository;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.domain.ExpressionValidationStatus;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.tables.DecisionTableService;import com.rulecraft.decisionops.tables.domain.TableValidationStatus;import com.rulecraft.decisionops.tests.DecisionTestService;import com.rulecraft.decisionops.tests.domain.TestCaseValidationStatus;import com.rulecraft.decisionops.versions.domain.*;import com.rulecraft.decisionops.versions.persistence.DecisionVersionRepository;
import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import tools.jackson.core.JacksonException;import tools.jackson.databind.*;

@Service
public class DecisionVersionService {
    private final DecisionVersionRepository versions;private final DecisionServiceRepository services;private final ProjectAccessPolicy access;private final CatalogService catalog;private final DecisionGraphService graphs;private final DecisionTableService tables;private final DecisionExpressionService expressions;private final DecisionTestService tests;private final AuditService audit;private final ObjectMapper mapper;private final Clock clock;
    public DecisionVersionService(DecisionVersionRepository versions,DecisionServiceRepository services,ProjectAccessPolicy access,CatalogService catalog,DecisionGraphService graphs,DecisionTableService tables,DecisionExpressionService expressions,DecisionTestService tests,AuditService audit,ObjectMapper mapper,Clock clock){this.versions=versions;this.services=services;this.access=access;this.catalog=catalog;this.graphs=graphs;this.tables=tables;this.expressions=expressions;this.tests=tests;this.audit=audit;this.mapper=mapper;this.clock=clock;}
    @Transactional(readOnly=true)public List<VersionSummary> list(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){context(actor,projectId,serviceId,false);return versions.findTop100ByDecisionServiceIdAndTenantIdAndProjectIdOrderByVersionNumberDesc(serviceId,actor.tenantId(),projectId).stream().map(this::summary).toList();}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)public WorkingState working(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){context(actor,projectId,serviceId,false);var service=catalog.getService(actor,projectId,serviceId);var graph=graphs.get(actor,projectId,serviceId);var built=build(actor,projectId,service,graph);return new WorkingState(service.version(),graph.version(),built.valid()?VersionValidationStatus.VALID:VersionValidationStatus.INVALID,fingerprint(actor,serviceId,built.content()));}
    @Transactional(isolation=Isolation.REPEATABLE_READ)public VersionSummary capture(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,CaptureCommand command){context(actor,projectId,serviceId,true);if(command==null||command.clientRequestId()==null)bad("RC-VERSION-REQUEST-ID","Provide a client request ID so capture retries remain idempotent.");var existing=versions.findByTenantIdAndDecisionServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(existing.isPresent())return summary(existing.get());var locked=services.lockForVersionCapture(serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);if(locked.getStatus()!=DecisionServiceStatus.ACTIVE)conflict("RC-VERSION-SERVICE-ARCHIVED","Restore the decision service before capturing a version.");var service=catalog.getService(actor,projectId,serviceId);var graph=graphs.get(actor,projectId,serviceId);if(command.expectedServiceVersion()==null||command.expectedServiceVersion()!=service.version()||command.expectedGraphVersion()==null||command.expectedGraphVersion()!=graph.version())conflict("RC-VERSION-STALE","The decision changed. Refresh before capturing a version.");var label=command.label()==null?"":command.label().strip();var note=command.note()==null||command.note().isBlank()?null:command.note().strip();if(label.isBlank()||label.length()>160)bad("RC-VERSION-LABEL","Version labels contain 1–160 characters.");if(note!=null&&note.length()>1000)bad("RC-VERSION-NOTE","Version notes contain at most 1000 characters.");if(versions.countByTenantIdAndDecisionServiceId(actor.tenantId(),serviceId)>=1000)bad("RC-VERSION-LIMIT","A decision service can retain at most 1000 captured versions.");var built=build(actor,projectId,service,graph);var fingerprint=fingerprint(actor,serviceId,built.content());if(command.expectedFingerprint()==null||!MessageDigest.isEqual(command.expectedFingerprint().getBytes(StandardCharsets.UTF_8),fingerprint.getBytes(StandardCharsets.UTF_8)))conflict("RC-VERSION-STALE","The decision changed. Refresh before capturing a version.");var latest=versions.findFirstByDecisionServiceIdAndTenantIdOrderByVersionNumberDesc(serviceId,actor.tenantId());if(latest.isPresent()&&latest.get().getFingerprint().equals(fingerprint))conflict("RC-VERSION-NO-CHANGES","The working decision has no semantic changes since the latest captured version.");var number=latest.map(value->value.getVersionNumber()+1).orElse(1);var root=new LinkedHashMap<String,Object>();root.put("sourceVersions",built.sourceVersions());root.put("content",built.content());var now=Instant.now(clock);DecisionVersion value;try{value=versions.saveAndFlush(new DecisionVersion(actor.tenantId(),projectId,serviceId,command.clientRequestId(),number,label,note,built.valid()?VersionValidationStatus.VALID:VersionValidationStatus.INVALID,fingerprint,json(root),service.version(),graph.version(),actor.userId(),now));}catch(DataIntegrityViolationException race){var duplicate=versions.findByTenantIdAndDecisionServiceIdAndClientRequestId(actor.tenantId(),serviceId,command.clientRequestId());if(duplicate.isPresent())return summary(duplicate.get());conflict("RC-VERSION-CONCURRENT","Another version was captured. Refresh the version history before retrying.");return null;}audit.record(actor.tenantId(),actor.userId(),"DECISION_VERSION_CAPTURED","DECISION_VERSION",value.getId(),Map.of("serviceId",serviceId,"versionNumber",number,"status",value.getValidationStatus().name()));return summary(value);}
    @Transactional(readOnly=true)public VersionDiff diff(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID baseId,UUID targetId){context(actor,projectId,serviceId,false);if(baseId==null||targetId==null||baseId.equals(targetId))bad("RC-VERSION-DIFF-SELECTION","Choose two different captured versions.");var base=require(actor,projectId,serviceId,baseId);var target=require(actor,projectId,serviceId,targetId);var before=parse(base.getSnapshotJson()).get("content");var after=parse(target.getSnapshotJson()).get("content");var changes=new ArrayList<SemanticChange>();compareMap(changes,ChangeCategory.CONTRACT,"service",before.get("service"),after.get("service"));compareMap(changes,ChangeCategory.CONTRACT,"types",before.get("types"),after.get("types"));compareMap(changes,ChangeCategory.CONTRACT,"inputs",before.get("inputs"),after.get("inputs"));compareMap(changes,ChangeCategory.CONTRACT,"outputs",before.get("outputs"),after.get("outputs"));compareMap(changes,ChangeCategory.GRAPH,"nodes",before.get("nodes"),after.get("nodes"));compareMap(changes,ChangeCategory.GRAPH,"edges",before.get("edges"),after.get("edges"));compareMap(changes,ChangeCategory.IMPLEMENTATION,"implementations",before.get("implementations"),after.get("implementations"));compareMap(changes,ChangeCategory.TEST,"tests",before.get("tests"),after.get("tests"));var breaking=(int)changes.stream().filter(change->change.impact()==ChangeImpact.BREAKING).count();var behavioral=(int)changes.stream().filter(change->change.impact()==ChangeImpact.BEHAVIORAL).count();return new VersionDiff(summary(base),summary(target),changes,breaking,behavioral,changes.size()-breaking-behavioral);}
    private Build build(RuleCraftPrincipal actor,UUID projectId,DecisionServiceView service,GraphView graph){var content=new LinkedHashMap<String,Object>();content.put("service",Map.of("serviceKey",service.serviceKey(),"name",service.name(),"description",service.description()==null?"":service.description()));var allTypes=catalog.listTypes(actor,projectId);var typeById=new HashMap<UUID,TypeView>();allTypes.forEach(type->typeById.put(type.id(),type));var referenced=new LinkedHashSet<UUID>();service.inputs().forEach(field->collectRef(field.type(),typeById,referenced));service.outputs().forEach(field->collectRef(field.type(),typeById,referenced));var typeContent=new TreeMap<String,Object>();referenced.stream().map(typeById::get).filter(Objects::nonNull).sorted(Comparator.comparing(TypeView::typeKey)).forEach(type->typeContent.put(type.typeKey(),typeSemantic(type)));content.put("types",typeContent);content.put("inputs",fields(service.inputs()));content.put("outputs",fields(service.outputs()));
        var nodeContent=new TreeMap<String,Object>();var portNames=new HashMap<UUID,String>();var nodeNames=new HashMap<UUID,String>();for(var node:graph.nodes()){nodeNames.put(node.id(),node.nodeKey());var ports=new TreeMap<String,Object>();for(var port:node.ports()){portNames.put(port.id(),port.portKey());ports.put(port.direction()+":"+port.portKey(),Map.of("label",port.label(),"type",typeRef(port.type(),typeById),"required",port.required(),"position",port.position()));}nodeContent.put(node.nodeKey(),Map.of("name",node.name(),"kind",node.kind().name(),"serviceFieldKey",node.serviceFieldKey()==null?"":node.serviceFieldKey(),"ports",ports));}content.put("nodes",nodeContent);var edgeContent=new TreeMap<String,Object>();for(var edge:graph.edges()){var sourceNode=owner(graph,edge.sourcePortId());var targetNode=owner(graph,edge.targetPortId());var key=nodeNames.get(sourceNode)+"."+portNames.get(edge.sourcePortId())+" -> "+nodeNames.get(targetNode)+"."+portNames.get(edge.targetPortId());edgeContent.put(key,true);}content.put("edges",edgeContent);
        var tableSummaries=tables.summaries(actor,projectId,service.id());var tableNodes=new HashSet<UUID>();tableSummaries.forEach(summary->tableNodes.add(summary.nodeId()));var expressionSummaries=expressions.summaries(actor,projectId,service.id());var expressionNodes=new HashSet<UUID>();expressionSummaries.forEach(summary->expressionNodes.add(summary.nodeId()));var implementations=new TreeMap<String,Object>();var implementationVersions=new TreeMap<String,Object>();boolean valid=graph.validationStatus()==GraphValidationStatus.VALID;for(var node:graph.nodes().stream().filter(candidate->candidate.kind()==GraphNodeKind.DECISION).sorted(Comparator.comparing(GraphNodeView::nodeKey)).toList()){if(tableNodes.contains(node.id())){var table=tables.find(actor,projectId,service.id(),node.id()).orElseThrow();var columns=table.inputs().stream().collect(java.util.stream.Collectors.toMap(DecisionTableService.ColumnView::portId,DecisionTableService.ColumnView::portKey));var rules=new ArrayList<Object>();for(var rule:table.rules()){var inputs=new TreeMap<String,Object>();for(var entry:rule.inputs())inputs.put(columns.get(entry.inputPortId()),Map.of("operator",entry.operator().name(),"value",entry.valueJson()==null?"":entry.valueJson()));rules.add(Map.of("id",rule.id().toString(),"enabled",rule.enabled(),"description",rule.description()==null?"":rule.description(),"inputs",inputs,"output",rule.outputValueJson()==null?"":rule.outputValueJson()));}implementations.put(node.nodeKey(),Map.of("kind","TABLE","hitPolicy",table.hitPolicy().name(),"rules",rules));implementationVersions.put(node.nodeKey(),table.version());valid&=table.validationStatus()==TableValidationStatus.VALID;}else if(expressionNodes.contains(node.id())){var expression=expressions.find(actor,projectId,service.id(),node.id()).orElseThrow();implementations.put(node.nodeKey(),Map.of("kind","EXPRESSION","language",expression.languageVersion(),"source",expression.source()));implementationVersions.put(node.nodeKey(),expression.version());valid&=expression.validationStatus()==ExpressionValidationStatus.VALID;}else{implementations.put(node.nodeKey(),Map.of("kind","NONE"));valid=false;}}content.put("implementations",implementations);
        var testContent=new TreeMap<String,Object>();var testVersions=new TreeMap<String,Object>();for(var test:tests.list(actor,projectId,service.id())){testContent.put(test.testKey(),Map.of("name",test.name(),"description",test.description()==null?"":test.description(),"inputs",test.inputs(),"expectedOutputs",test.expectedOutputs(),"validationStatus",test.validationStatus().name()));testVersions.put(test.testKey(),test.version());valid&=test.validationStatus()==TestCaseValidationStatus.VALID;}content.put("tests",testContent);var source=new LinkedHashMap<String,Object>();source.put("service",service.version());source.put("graph",graph.version());source.put("implementations",implementationVersions);source.put("tests",testVersions);return new Build(content,source,valid);}
    private String fingerprint(RuleCraftPrincipal actor,UUID serviceId,Map<String,Object> content){var latest=versions.findFirstByDecisionServiceIdAndTenantIdOrderByVersionNumberDesc(serviceId,actor.tenantId());return DecisionContentIdentity.fingerprint(mapper,content,latest.map(value->parse(value.getSnapshotJson()).path("content")).orElse(null),latest.map(DecisionVersion::getFingerprint).orElse(null));}
    private void collectRef(TypeRefView ref,Map<UUID,TypeView> types,Set<UUID> result){if(ref==null||ref.customTypeId()==null||!result.add(ref.customTypeId()))return;var type=types.get(ref.customTypeId());if(type==null)return;collectRef(type.itemType(),types,result);type.fields().forEach(field->collectRef(field.type(),types,result));}private Object typeSemantic(TypeView type){var value=new LinkedHashMap<String,Object>();value.put("name",type.name());value.put("description",type.description()==null?"":type.description());value.put("kind",type.kind().name());if(type.itemType()!=null)value.put("itemType",typeRef(type.itemType(),Map.of(type.id(),type)));value.put("fields",fields(type.fields()));var enums=new TreeMap<String,Object>();type.values().forEach(item->enums.put(item.value(),item.label()));value.put("values",enums);return value;}private Map<String,Object> fields(List<FieldView> fields){var result=new TreeMap<String,Object>();for(var field:fields)result.put(field.fieldKey(),Map.of("label",field.label(),"type",typeRef(field.type(),Map.of()),"required",field.required()));return result;}private String typeRef(TypeRefView ref,Map<UUID,TypeView> ignored){return ref.builtinType()!=null?ref.builtinType().name():"CUSTOM:"+ref.customTypeKey();}private String typeRef(DecisionGraphService.TypeRefCommand ref,Map<UUID,TypeView> types){if(ref.builtinType()!=null)return ref.builtinType().name();var type=types.get(ref.customTypeId());return "CUSTOM:"+(type==null?ref.customTypeId():type.typeKey());}private UUID owner(GraphView graph,UUID portId){return graph.nodes().stream().filter(node->node.ports().stream().anyMatch(port->port.id().equals(portId))).map(GraphNodeView::id).findFirst().orElse(null);}
    private void compareMap(List<SemanticChange> changes,ChangeCategory category,String prefix,JsonNode before,JsonNode after){if(before==null||after==null){if(!Objects.equals(before,after))changes.add(change(category,prefix,before,after));return;}if(!before.isObject()||!after.isObject()){if(!before.equals(after))changes.add(change(category,prefix,before,after));return;}var keys=new TreeSet<String>();before.propertyNames().forEach(keys::add);after.propertyNames().forEach(keys::add);for(var key:keys){var left=before.get(key);var right=after.get(key);if(!Objects.equals(left,right))changes.add(change(category,prefix+"."+key,left,right));}}
    private SemanticChange change(ChangeCategory category,String path,JsonNode before,JsonNode after){var kind=before==null?ChangeKind.ADDED:after==null?ChangeKind.REMOVED:ChangeKind.CHANGED;var metadata=path.equals("service.name")||path.equals("service.description");var impact=category==ChangeCategory.IMPLEMENTATION||category==ChangeCategory.GRAPH?ChangeImpact.BEHAVIORAL:category==ChangeCategory.CONTRACT&&kind!=ChangeKind.ADDED&&!metadata?ChangeImpact.BREAKING:ChangeImpact.NON_BREAKING;return new SemanticChange(category,kind,impact,path,path.substring(path.lastIndexOf('.')+1),before,after);}
    private void context(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,boolean edit){if(edit)access.requireEdit(actor,projectId);else access.requireVisible(actor,projectId);catalog.getService(actor,projectId,serviceId);}private DecisionVersion require(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID id){return versions.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(id,serviceId,actor.tenantId(),projectId).orElseThrow(this::notFound);}private DomainProblemException notFound(){return new DomainProblemException(HttpStatus.NOT_FOUND,"RC-VERSION-NOT-FOUND","Captured decision version not found.");}private VersionSummary summary(DecisionVersion value){return new VersionSummary(value.getId(),value.getVersionNumber(),value.getLabel(),value.getNote(),value.getValidationStatus(),value.getFingerprint(),value.getSourceServiceVersion(),value.getSourceGraphVersion(),value.getCapturedAt());}
    private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JacksonException failure){throw new IllegalStateException("Decision version could not be serialized.",failure);}}private JsonNode parse(String value){try{return mapper.readTree(value);}catch(JacksonException failure){throw new IllegalStateException("Persisted decision version is invalid.",failure);}}private void bad(String code,String message){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}private void conflict(String code,String message){throw new DomainProblemException(HttpStatus.CONFLICT,code,message);}
    private record Build(Map<String,Object> content,Map<String,Object> sourceVersions,boolean valid){}
    public record CaptureCommand(UUID clientRequestId,String label,String note,Long expectedServiceVersion,Long expectedGraphVersion,String expectedFingerprint){}public record WorkingState(long serviceVersion,long graphVersion,VersionValidationStatus validationStatus,String fingerprint){}public record VersionSummary(UUID id,int versionNumber,String label,String note,VersionValidationStatus validationStatus,String fingerprint,long sourceServiceVersion,long sourceGraphVersion,Instant capturedAt){}public enum ChangeCategory{CONTRACT,GRAPH,IMPLEMENTATION,TEST}public enum ChangeKind{ADDED,REMOVED,CHANGED}public enum ChangeImpact{BREAKING,BEHAVIORAL,NON_BREAKING}public record SemanticChange(ChangeCategory category,ChangeKind kind,ChangeImpact impact,String path,String label,JsonNode before,JsonNode after){}public record VersionDiff(VersionSummary base,VersionSummary target,List<SemanticChange> changes,int breakingCount,int behavioralCount,int nonBreakingCount){}
}
